//! The stage-algebra relation on a real fibonacci 2^18 proof: the R1CS is
//! built from the profile alone, the witness is generated by replaying the
//! native verifier, and `check_witness` must pass. Tampering with a round
//! coefficient or an outsourced public input must fail inside the owning
//! stage's rows.
//!
//! `cargo nextest run -p jolt-wrapper --features prover-fixtures --cargo-quiet -E 'binary(relation_fixture)' --no-capture`

#![cfg(feature = "prover-fixtures")]
#![expect(clippy::expect_used, clippy::print_stdout, clippy::unwrap_used)]

